g2=[[0]*20 for _ in range(20)]; ones=[(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)]
for r in range(2,9):
 for c in range(9,16):g2[r][c]=2
# horizontal extensions: marked side disabled; opposite side to edge; if no marker, both
for r in range(2,9):
 bs=[c for rr,c in ones if rr==r]
 if not any(c<9 for c in bs):
  for c in range(0,9):g2[r][c]=2
 if not any(c>15 for c in bs):
  for c in range(16,20):g2[r][c]=2
# vertical, marker side disabled; upward no markers, downward excludes marked columns
for c in range(9,16):
 for r in range(0,2):g2[r][c]=2
 if not any(cc==c and r>8 for r,cc in ones):
  for r in range(9,20):g2[r][c]=2
for r,c in ones:g2[r][c]=1
print('\n'.join(' '.join(map(str,row)) for row in g2))
